const useLocalStorage = <T,>(key: string, initialValue: T | (() => T)) => {
    const [storedValue, setStoredValue] = useState<T>(() => {
        try {
            const item = window.localStorage.getItem(key);
            if (item) {
                const parsed = JSON.parse(item);
                // Handle special cases like dates which are stringified
                if (key === 'tw_chatMessages') {
                    return parsed.map((msg: ChatMessage) => ({...msg, timestamp: new Date(msg.timestamp)}));
                }
                return parsed;
            }
        } catch (error) {
            console.error(error);
        }
        return initialValue instanceof Function ? initialValue() : initialValue;
    });

    useEffect(() => {
        try {
            window.localStorage.setItem(key, JSON.stringify(storedValue));
        } catch (error) {
            console.error(error);
        }
    }, [key, storedValue]);

    return [storedValue, setStoredValue] as const;
};

export type TimePeriod = 'this_week' | 'this_month' | 'last_month';

const getFilteredEntriesForPeriod = (entries: Entry[], timePeriod: TimePeriod): Entry[] => {
    const now = new Date();
    let startDate: Date;
    let endDate: Date = new Date(now);
    endDate.setHours(23, 59, 59, 999); // end of today

    switch (timePeriod) {
        case 'this_week':
            startDate = new Date(now);
            const dayOfWeek = now.getDay();
            const diff = now.getDate() - dayOfWeek + (dayOfWeek === 0 ? -6 : 1); // adjust when day is sunday
            startDate.setDate(diff);
            startDate.setHours(0, 0, 0, 0);
            break;
        case 'last_month':
            startDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
            endDate = new Date(now.getFullYear(), now.getMonth(), 0);
            endDate.setHours(23, 59, 59, 999);
            break;
        case 'this_month':
        default:
            startDate = new Date(now.getFullYear(), now.getMonth(), 1);
            break;
    }

    return entries.filter(e => {
      const [year, month, day] = e.date.split('-').map(Number);
      // Month is 0-indexed for the Date constructor
      const entryDate = new Date(year, month - 1, day);
      return entryDate >= startDate && entryDate <= endDate;
    });
};


const useMockData = () => {
