                                const repMonthlyGoal = totalMonthlyGoal / numReps;
                                const periodGoal = getGoalForPeriod(repMonthlyGoal, timePeriod);
                                const currentValue = progress[key] || 0;

                                // Calculate percentage and determine status
                                const percentage = periodGoal > 0 ? (currentValue / periodGoal) * 100 : 0;

                                let progressColor: 'green' | 'yellow' | 'red' = 'red';
                                let statusLabel = 'Needs Focus';
                                let statusTextColor = 'text-red-400';

                                if (percentage >= 100) {
                                    progressColor = 'green';
                                    statusLabel = 'Goal Met!';
                                    statusTextColor = 'text-green-400';
                                } else if (percentage >= 70) {
                                    progressColor = 'yellow';
                                    statusLabel = 'Close';
                                    statusTextColor = 'text-yellow-400';
                                }

                                const isCurrency = key === 'accessories';
                                const details = KPI_DETAILS[key];
                                const Icon = details.icon;

                                return (
                                    <div key={key} className="group">
                                        <div className="flex justify-between items-end mb-2">
                                            <div className="flex items-center gap-3">
                                                <div className={`p-2.5 rounded-xl bg-gray-700/30 group-hover:bg-gray-700/60 transition-colors border border-gray-700/50`}>
                                                    <Icon className={`w-5 h-5 ${details.color}`} />
                                                </div>
                                                <div>
                                                    <div className="flex items-center gap-2">
                                                        <p className="text-sm font-bold text-gray-200">{KPI_NAMES_REPS[key]}</p>
                                                        {periodGoal > 0 && (
                                                             <span className={`text-[10px] font-extrabold uppercase tracking-wider px-1.5 py-0.5 rounded-sm bg-gray-900/50 ${statusTextColor}`}>
                                                                {statusLabel}
                                                            </span>
                                                        )}
                                                    </div>
                                                    <p className="text-xs text-gray-500 font-medium mt-0.5">Target: {isCurrency && '$'}{Math.round(periodGoal).toLocaleString()}</p>
                                                </div>
                                            </div>
                                            <div className="text-right">
                                                <div className="flex items-center justify-end gap-3">
                                                    <p className="text-white font-bold text-xl tabular-nums">
                                                        {isCurrency && '$'}{currentValue.toLocaleString()}
                                                    </p>
                                                    <KpiAdjuster
                                                        value={currentValue}
                                                        isCurrency={isCurrency}
                                                        onAdjust={(adjustment) => handleRepStatUpdate(rep.id, key, adjustment)}
                                                    />
                                                </div>
                                            </div>
                                        </div>

                                        <div className="relative mt-2">
                                            <ProgressBar percentage={percentage} color={progressColor} height="h-3" />
                                        </div>
                                    </div>
                                )
                             })}
                        </div>
                    </div>
                ))}
            </div>

            {isLogSaleModalOpen && selectedRepForSale && (
                <LogSaleModal rep={selectedRepForSale} onClose={() => setIsLogSaleModalOpen(false)} addEntry={addEntry} />
            )}
             <style>{`
                .tabular-nums {
                    font-variant-numeric: tabular-nums;
                }
                .animate-fadeIn {
                    animation: fadeIn 0.2s ease-out forwards;
                }
                @keyframes fadeIn {
                    from { opacity: 0; transform: scale(0.95); }
                    to { opacity: 1; transform: scale(1); }
                }
            `}</style>
        </div>
    );
};


const TeamChat: React.FC<TeamChatProps> = ({ messages, reps, addMessage }) => {
    const [newMessage, setNewMessage] = useState('');
    const [currentUser] = useState(reps.length > 0 ? reps[0] : null);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }

    useEffect(scrollToBottom, [messages]);

    const handleSendMessage = (e: React.FormEvent) => {
        e.preventDefault();
        if (newMessage.trim() === '' || !currentUser) return;

        addMessage({
            user: currentUser,
            text: newMessage,
        });
        setNewMessage('');
    };

    if (!currentUser) {
        return (
             <div className="flex flex-col h-[calc(100vh-10rem)] items-center justify-center text-center">
                <ChatIcon className="h-16 w-16 text-gray-700 mb-6" />
                <h2 className="text-2xl font-bold text-white">No Reps Available</h2>
                <p className="text-gray-400 mt-3 max-w-md">Please add a sales representative in the Admin Center to enable team chat and performance tracking.</p>
            </div>
        )
    }

    return (
        <div className="flex flex-col h-[calc(100vh-4rem)] max-w-5xl mx-auto">
             <div className="mb-6">
                 <h1 className="text-3xl font-bold text-white flex items-center gap-3">
                    <div className="p-2 bg-red-600/20 rounded-lg">
                        <ChatIcon className="h-8 w-8 text-red-500" />
                    </div>
                    Team Chat
                </h1>
                <p className="text-base text-gray-400 mt-1 ml-1">Collaborate, celebrate wins, and share updates with the squad.</p>
            </div>

            <div className="flex-1 bg-gray-800 border border-gray-700 rounded-2xl shadow-xl flex flex-col overflow-hidden">
                <div className="flex-1 p-6 space-y-6 overflow-y-auto bg-gradient-to-b from-gray-800 to-gray-900">
                    {messages.length === 0 && (
                         <div className="flex flex-col items-center justify-center h-full text-gray-600 opacity-50">
                            <ChatIcon className="w-12 h-12 mb-2"/>
                            <p>No messages yet. Start the conversation!</p>
                         </div>
                    )}
                    {messages.map((msg) => {
                        const isCurrentUser = msg.user.id === currentUser.id;
                        return (
                            <div key={msg.id} className={`flex items-end gap-3 ${isCurrentUser ? 'justify-end' : ''}`}>
                                {!isCurrentUser && (
                                    <div className="w-8 h-8 rounded-full bg-gray-700 text-gray-300 flex items-center justify-center font-bold text-xs flex-shrink-0 border border-gray-600">{msg.user.avatar}</div>
                                )}
                                <div className={`max-w-[75%] p-4 rounded-2xl shadow-md ${isCurrentUser ? 'bg-red-600 text-white rounded-br-sm' : 'bg-gray-700 text-gray-100 rounded-bl-sm'}`}>
                                    {!isCurrentUser && <p className="font-bold text-xs text-red-300 mb-1">{msg.user.name}</p>}
                                    <p className="text-sm leading-relaxed">{msg.text}</p>
                                    <p className={`text-[10px] mt-2 opacity-60 ${isCurrentUser ? 'text-red-100' : 'text-gray-400'} text-right`}>{msg.timestamp.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}</p>
                                </div>
                                {isCurrentUser && (
                                    <div className="w-8 h-8 rounded-full bg-red-500 text-white flex items-center justify-center font-bold text-xs flex-shrink-0 border-2 border-gray-800 shadow-sm">{msg.user.avatar}</div>
                                )}
                            </div>
                        );
                    })}
                    <div ref={messagesEndRef} />
                </div>
                <div className="p-5 bg-gray-800 border-t border-gray-700">
                    <form onSubmit={handleSendMessage} className="flex items-center gap-3">
                        <input
                            type="text"
                            value={newMessage}
                            onChange={(e) => setNewMessage(e.target.value)}
                            placeholder="Type your message..."
                            className="flex-1 bg-gray-700/50 border-gray-600 text-white rounded-xl shadow-inner focus:ring-2 focus:ring-red-500 focus:border-transparent sm:text-sm px-5 py-3 transition-all"
                        />
                        <button type="submit" className="bg-red-600 hover:bg-red-700 text-white font-bold p-3 rounded-xl shadow-lg shadow-red-600/20 transition-all transform active:scale-95" disabled={!newMessage.trim()}>
                             <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5">
                                <path d="M3.478 2.405a.75.75 0 00-.926.94l2.432 7.905H13.5a.75.75 0 010 1.5H4.984l-2.432 7.905a.75.75 0 00.926.94 60.519 60.519 0 0018.445-8.986.75.75 0 000-1.218A60.517 60.517 0 003.478 2.405z" />
                            </svg>
                        </button>
                    </form>
                </div>
            </div>
        </div>
    );
};


export default TeamChat;
